105	// TestRegisterRejectsInvalidUTF8：提案编号或任意一项动作原文含有非法 UTF-8
106	// 字节（非法首字节、残缺多字节序列、UTF-8 形式直接编码的代理码位）时整项
107	// 登记失败，错误分类为 ErrInvalidRegistration，且说明是编号还是动作原文、
108	// 动作在提交列表中的位置（0 起）；状态文件逐字节保持原样，不新增提案。
109	func TestRegisterRejectsInvalidUTF8(t *testing.T) {
110		store, path := openTempStore(t, 1000)
111		defer store.Close()
112	
113		// 状态中先存在一项编号含真实 U+FFFD 的合法提案与一项普通提案，
114		// 验证失败不重试/覆盖已有内容，已有提案与余额不受影响。
115		mustRegister(t, store, "gip-�", 100, "transfer:audits:10")
116		mustRegister(t, store, "gip-ok", 100, "transfer:legal:5")
117		before, err := os.ReadFile(path)
118		if err != nil {
119			t.Fatalf("read state: %v", err)
120		}
121	
122		cases := []struct {
123			name      string
124			id        string
125			actions   []string
126			wantInErr []string
127		}{
128			{"proposal id illegal byte", "gip-\xff", []string{"transfer:a:1"}, []string{"proposal id", "UTF-8"}},
129			{"proposal id truncated rune", "gip-\xe4\xb8", []string{"transfer:a:1"}, []string{"proposal id", "UTF-8"}}, // “中”缺少最后一个字节
130			{"proposal id encoded surrogate", "gip-\xed\xa0\x80", []string{"transfer:a:1"}, []string{"proposal id", "UTF-8"}}, // UTF-8 形式直接编码的 U+D800
131			{"action text illegal byte", "gip-bad-a0", []string{"transfer:audits:\xff"}, []string{"action 0", "UTF-8"}},
132			{"action text truncated rune", "gip-bad-a1", []string{"transfer:a:1", "\xf0\x9f\x98"}, []string{"action 1", "UTF-8"}}, // 表情缺少最后一个字节
133			{"action text encoded surrogate", "gip-bad-a2", []string{"ok", "also-ok", "\xed\xb0\x80"}, []string{"action 2", "UTF-8"}}, // UTF-8 形式直接编码的 U+DC00
134		}
135		for _, tc := range cases {
136			t.Run(tc.name, func(t *testing.T) {
137				existed, err := store.Register(tc.id, 100, tc.actions)
138				if err == nil || existed {
139					t.Fatalf("expected rejection, existed=%v err=%v", existed, err)
140				}
141				if !errors.Is(err, ErrInvalidRegistration) {
142					t.Fatalf("err=%v, want ErrInvalidRegistration", err)
143				}
144				for _, want := range tc.wantInErr {
145					if !strings.Contains(err.Error(), want) {
146						t.Fatalf("err=%q, want substring %q", err.Error(), want)
147					}
148				}
149			})
150		}
151	
152		// 非法字节输入落盘时会被改写成真实 U+FFFD，恰好等于已存在的合法编号：
153		// 仍必须整项失败（ErrInvalidRegistration），不得当作该编号的相同内容重试，
154		// 也不得报普通内容冲突。
155		if existed, err := store.Register("gip-\xef\xbf", 100, []string{"transfer:audits:10"}); err == nil || existed ||
156			!errors.Is(err, ErrInvalidRegistration) {
157			t.Fatalf("invalid-UTF-8 collision with real U+FFFD id: existed=%v err=%v", existed, err)
158		}
159		// 提交的动作与已有登记只有一处非法字节不同：同样是编码错误，不是内容冲突。
160		if existed, err := store.Register("gip-ok", 100, []string{"transfer:legal:\xff"}); err == nil || existed ||
161			!errors.Is(err, ErrInvalidRegistration) {
162			t.Fatalf("invalid action against existing id: existed=%v err=%v", existed, err)
163		}
164	
165		// 状态文件逐字节保持原样；已有合法提案仍可按原编号查询。
166		after, err := os.ReadFile(path)
167		if err != nil {
168			t.Fatalf("read state: %v", err)
169		}
170		if string(after) != string(before) {
171			t.Fatalf("state file changed after rejected registrations")
172		}
173		record, ok, err := store.Proposal("gip-�")
174		if err != nil || !ok || record.ID != "gip-�" {
175			t.Fatalf("existing U+FFFD proposal: ok=%v err=%v record=%+v", ok, err, record)
176		}
177		if bal, err := store.TreasuryBalance(); err != nil || bal != 1000 {
178			t.Fatalf("treasury changed: bal=%d err=%v", bal, err)
179		}
180	}
