1423	func itoa(i int) string {
1424		if i == 0 {
1425			return "0"
1426		}
1427		neg := i < 0
1428		if neg {
1429			i = -i
1430		}
1431		var buf [20]byte
1432		pos := len(buf)
1433		for i > 0 {
1434			pos--
1435			buf[pos] = byte('0' + i%10)
1436			i /= 10
1437		}
1438		if neg {
1439			pos--
1440			buf[pos] = '-'
1441		}
1442		return string(buf[pos:])
1443	}
