1804			if err != nil || len(receipts) != 2 {
1805				t.Fatalf("receipts=%v err=%v", receipts, err)
1806			}
1807			r0, r1 := receipts[0], receipts[1]
1808			if r0.ProposalID != "gip-a" || r0.Order != 0 ||
1809				r1.ProposalID != "gip-v" || r1.Order != 1 {
