843		// 用结构化改写构造损坏变体，避免依赖具体缩进。
844		mutate := func(fn func(p map[string]any)) []byte {
845			var clone map[string]any
846			if err := json.Unmarshal(good, &clone); err != nil {
847				t.Fatal(err)
848			}
