1834		path := filepath.Join(dir, "treasury.json")
1835		store, err := InitTreasury(path, 1000)
1836		if err != nil {
1837			t.Fatal(err)
1838		}
1839		// gip-tally-ops：已计票通过（for=600/against=0）；gip-still-voting：仍在投票。
1840		mustCreateVote(t, store, baseVoteInput("gip-tally-ops"))
1841		if _, err := store.CastVote("gip-tally-ops", "alice", true, 150); err != nil {
1842			t.Fatal(err)
1843		}
