1845			t.Fatal(err)
1846		}
1847		mustCreateVote(t, store, baseVoteInput("gip-still-voting"))
1848		mustRegister(t, store, "gip-spent", 0, "transfer:audits:100")
1849		if _, err := store.Execute("gip-spent", 0); err != nil {
1850			t.Fatal(err)
1851		}
1852		store.Close()
1853	
1854		good, err := os.ReadFile(path)
1855		if err != nil {
1856			t.Fatal(err)
1857		}
1858		var clone map[string]any
1859		if err := json.Unmarshal(good, &clone); err != nil {
1860			t.Fatal(err)
1861		}
1862		// 删除已计票结果的 against_weight：真实反对票重恰好为 0，
1863		// 若被默认补零，这份缺损记录会被误当成有效的首次计票结果。
1864		delete(clone["vote_proposals"].(map[string]any)["gip-tally-ops"].(map[string]any)["tally"].(map[string]any), "against_weight")
1865		bad, err := json.MarshalIndent(clone, "", "  ")
1866		if err != nil {
1867			t.Fatal(err)
1868		}
1869		bad = append(bad, '\n')
1870		if err := os.WriteFile(path, bad, 0o600); err != nil {
1871			t.Fatal(err)
1872		}
1873	
1874		// 打开即拒绝，不返回可用句柄。
1875		s, err := Open(path)
1876		if !errors.Is(err, ErrStateCorrupt) {
1877			t.Fatalf("Open err=%v, want ErrStateCorrupt", err)
1878		}
1879		if s != nil {
1880			t.Fatal("corrupt open must not return a usable store")
1881		}
1882		if got, rerr := os.ReadFile(path); rerr != nil || string(got) != string(bad) {
1883			t.Fatalf("corrupt file was normalized or rewritten")
1884		}
1885	
1886		// 用一个真实打开的句柄，随后在句柄之外把文件改坏，下一次读取/操作必须拒绝。
1887		recoverPath := filepath.Join(dir, "recover.json")
1888		if err := os.WriteFile(recoverPath, good, 0o600); err != nil {
1889			t.Fatal(err)
