	if _, err := store.CastVote("gip-incomplete", "dave", false, 150); err != nil {
		t.Fatal(err)
	}
	// 另有一笔已执行支出，便于断言失败后资金余额与文件内容原样保留。
	mustRegister(t, store, "gip-spent", 0, "transfer:audits:100")
