	}
	// 成员原始权重与完整委托路径逐字保留（bob→alice、carol→alice）。
	wantWeight := map[string]int64{"alice": 300, "bob": 200, "carol": 100, "dave": 400}
	wantPath := map[string][]string{
		"alice": {"alice"},
		"bob":   {"bob", "alice"},
		"carol": {"carol", "alice"},
		"dave":  {"dave"},
	}
	if len(v.Members) != 4 {
